public class TextDocumentAnalysis {
    public static void main(String[] args){
        Scanner input = new Scanner(System.in);
        int total = input.nextInt();
        String s = input.next();
        s = s.toLowerCase();
        int maxCount = -1;
        int countWords = 0;
        int nestingLevel = 0;
        int underlineSequence = 0;
        for(int i=0; i<total; i++){
            char ch = s.charAt(i);
            if(ch == '(') {nestingLevel++; underlineSequence=0;}
            else if(ch == ')') {
                if(nestingLevel == 1 && underlineSequence != 0) countWords++;
                nestingLevel--; underlineSequence=0;
            }
            else if(ch == '_') {
                if(nestingLevel == 1 && underlineSequence != 0) countWords++;
                underlineSequence=0;
            }
            else {
                underlineSequence++;
            }
            if(nestingLevel==0) maxCount = Math.max(underlineSequence, maxCount);
        }
        System.out.println(maxCount + " " + countWords);
    }
}
