#include <iostream>
#include <string>
#include <algorithm>

int main() {
    int total;
    std::cin >> total;
    std::string s;
    std::cin >> s;
    for (auto &c : s) c = tolower(c);
    int maxCount = -1;
    int countWords = 0;
    int nestingLevel = 0;
    int underlineSequence = 0;
    for (int i = 0; i < total; i++) {
        char ch = s[i];
        if (ch == '(') {
            nestingLevel++;
            underlineSequence = 0;
        } else if (ch == ')') {
            if (nestingLevel == 1 && underlineSequence != 0) countWords++;
            nestingLevel--;
            underlineSequence = 0;
        } else if (ch == '_') {
            if (nestingLevel == 1 && underlineSequence != 0) countWords++;
            underlineSequence = 0;
        } else {
            underlineSequence++;
        }
        if (nestingLevel == 0) maxCount = std::max(underlineSequence, maxCount);
    }
    std::cout << maxCount << " " << countWords << std::endl;
    return 0;
}
